WITH gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, session_start_flag, island_id, CASE WHEN device_code RLIKE '^(DV-01|DV-02)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS device_code_zone FROM islands;
